import pandas as pd
import numpy as np

def calculate_team_tiers(team_stats: pd.DataFrame) -> pd.DataFrame:
    if team_stats.empty:
        return pd.DataFrame(columns=['team_id', 'team_name', 'points', 'position', 'tier'])

    team_stats['points'] = team_stats['wins'] * 3 + team_stats['draws'] * 1
    team_stats['position'] = team_stats['points'].rank(method='min', ascending=False).astype(int)

    total = len(team_stats)
    t1_bound = np.ceil(total * 0.33)
    t2_bound = np.ceil(total * 0.66)

    def get_tier(pos):
        if pos <= t1_bound:
            return 'Tier 1'
        elif pos <= t2_bound:
            return 'Tier 2'
        else:
            return 'Tier 3'

    team_stats['tier'] = team_stats['position'].apply(get_tier)
    result = team_stats[['team_id', 'team_name', 'points', 'position', 'tier']]
    return result.sort_values(by=['points', 'team_name'], ascending=[False, True])
